"use client";

import {
  Check,
  CircleAlert,
  LoaderCircle,
  OctagonAlert,
  ShieldCheck,
  TriangleAlert,
  X,
} from "lucide-react";
import {
  type ComponentProps,
  createContext,
  type ReactNode,
  useContext,
  useEffect,
  useId,
  useState,
} from "react";

import { cn } from "@/lib/uai-utils";

export const APPROVAL_CARD_RISKS = ["low", "medium", "high", "critical"] as const;
export const APPROVAL_CARD_VARIANTS = ["compact", "detailed"] as const;
export const APPROVAL_CARD_STATUSES = [
  "ready",
  "submitting",
  "approved",
  "rejected",
  "error",
] as const;

export type ApprovalRisk = (typeof APPROVAL_CARD_RISKS)[number];
export type ApprovalCardVariant = (typeof APPROVAL_CARD_VARIANTS)[number];
export type ApprovalCardStatus = (typeof APPROVAL_CARD_STATUSES)[number];
export type ApprovalDecision = "approved" | "rejected";

export type ApprovalConfirmation = {
  phrase: string;
  label?: ReactNode;
  placeholder?: string;
};

type ApprovalRiskProps =
  | { risk?: Exclude<ApprovalRisk, "critical">; confirmation?: never }
  | { risk: "critical"; confirmation: ApprovalConfirmation };

export type ApprovalCardState =
  | { status?: "ready"; pendingDecision?: never }
  | { status: "submitting"; pendingDecision: ApprovalDecision }
  | { status: "approved" | "rejected" | "error"; pendingDecision?: never };

export type ApprovalCardProps = ComponentProps<"section"> &
  ApprovalRiskProps &
  ApprovalCardState & {
    variant?: ApprovalCardVariant;
    disabled?: boolean;
  };

const riskConfig = {
  low: {
    label: "Low risk",
    icon: ShieldCheck,
    iconClassName:
      "bg-[color-mix(in_oklab,var(--uai-success)_14%,transparent)] text-[var(--uai-success)]",
  },
  medium: {
    label: "Medium risk",
    icon: CircleAlert,
    iconClassName:
      "bg-[color-mix(in_oklab,var(--uai-warning)_14%,transparent)] text-[var(--uai-warning)]",
  },
  high: {
    label: "High risk",
    icon: TriangleAlert,
    iconClassName:
      "bg-[color-mix(in_oklab,var(--uai-danger)_14%,transparent)] text-[var(--uai-danger)]",
  },
  critical: {
    label: "Critical risk",
    icon: OctagonAlert,
    iconClassName:
      "bg-[color-mix(in_oklab,var(--uai-danger)_14%,transparent)] text-[var(--uai-danger)] shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--uai-danger)_28%,transparent)]",
  },
} satisfies Record<
  ApprovalRisk,
  { label: string; icon: typeof ShieldCheck; iconClassName: string }
>;

const approvalCss = `
@keyframes uai-approval-shimmer{from{background-position:100% 0}to{background-position:-100% 0}}
[data-uai-approval] [data-shimmer]{background-image:linear-gradient(90deg,var(--uai-subtle) 0%,var(--uai-subtle) 35%,var(--uai-text) 50%,var(--uai-subtle) 65%,var(--uai-subtle) 100%);background-size:200% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:uai-approval-shimmer 2s linear infinite}
@media (prefers-reduced-motion:reduce){[data-uai-approval] [data-shimmer]{animation:none;background:none;color:var(--uai-muted)}}
`;

type ApprovalCardContextValue = {
  risk: ApprovalRisk;
  variant: ApprovalCardVariant;
  status: ApprovalCardStatus;
  pendingDecision?: ApprovalDecision;
  confirmation?: ApprovalConfirmation;
  confirmationValue: string;
  setConfirmationValue: (value: string) => void;
  confirmationMatches: boolean;
  disabled: boolean;
  isSubmitting: boolean;
  isTerminal: boolean;
  isActionable: boolean;
  titleId: string;
  confirmationId: string;
};

const ApprovalCardContext = createContext<ApprovalCardContextValue | null>(null);

function useApprovalCard(name: string) {
  const context = useContext(ApprovalCardContext);
  if (!context) throw new Error(`${name} must be used within ApprovalCard`);
  return context;
}

export function ApprovalCard(props: ApprovalCardProps) {
  const {
    variant = "compact",
    risk = "medium",
    confirmation,
    status = "ready",
    pendingDecision,
    disabled = false,
    children,
    className,
    style,
    "aria-labelledby": ariaLabelledby,
    ...sectionProps
  } = props;
  const titleId = useId();
  const confirmationId = useId();
  const [confirmationValue, setConfirmationValue] = useState("");
  const isSubmitting = status === "submitting";
  const isTerminal = status === "approved" || status === "rejected";
  const isActionable = status === "ready" || status === "error";
  const confirmationMatches =
    risk !== "critical" ||
    (Boolean(confirmation?.phrase) && confirmationValue === confirmation?.phrase);

  useEffect(() => {
    setConfirmationValue((current) => (current === confirmation?.phrase ? current : ""));
  }, [confirmation?.phrase]);

  const context: ApprovalCardContextValue = {
    risk,
    variant,
    status,
    pendingDecision,
    confirmation,
    confirmationValue,
    setConfirmationValue,
    confirmationMatches,
    disabled,
    isSubmitting,
    isTerminal,
    isActionable,
    titleId,
    confirmationId,
  };

  return (
    <ApprovalCardContext.Provider value={context}>
      <section
        {...sectionProps}
        className={cn(
          "border bg-[var(--uai-surface)] text-[var(--uai-text)] transition-[border-color,opacity] duration-150 motion-reduce:transition-none",
          variant === "compact" ? "p-3.5" : "p-4",
          risk === "critical"
            ? "border-[color-mix(in_oklab,var(--uai-danger)_40%,var(--uai-border))]"
            : "border-[var(--uai-border)]",
          disabled && "opacity-55",
          className,
        )}
        style={{ ...style, borderRadius: 14 }}
        aria-busy={isSubmitting}
        aria-labelledby={ariaLabelledby ?? titleId}
        data-uai-approval=""
        data-risk={risk}
        data-status={status}
      >
        <style>{approvalCss}</style>
        {children}
      </section>
    </ApprovalCardContext.Provider>
  );
}

export type ApprovalCardHeaderProps = Omit<ComponentProps<"div">, "title"> & {
  title: ReactNode;
  description?: ReactNode;
  riskLabel?: ReactNode;
  statusLabel?: ReactNode;
};

export function ApprovalCardHeader({
  title,
  description,
  riskLabel,
  statusLabel,
  className,
  ...props
}: ApprovalCardHeaderProps) {
  const context = useApprovalCard("ApprovalCardHeader");
  const riskState = riskConfig[context.risk];
  const RiskIcon = riskState.icon;
  const resolvedStatusLabel =
    statusLabel ??
    {
      ready: "Ready for review",
      submitting: context.pendingDecision === "rejected" ? "Rejecting…" : "Approving…",
      approved: "Approved",
      rejected: "Rejected",
      error: "Decision failed",
    }[context.status];

  return (
    <div className={cn("flex items-start gap-3", className)} {...props}>
      <span
        className={cn(
          "grid size-8 shrink-0 place-items-center rounded-[10px]",
          riskState.iconClassName,
        )}
      >
        <RiskIcon className="size-4" strokeWidth={1.75} aria-hidden="true" />
      </span>
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1">
          <span
            className={cn(
              "inline-flex items-center rounded-full px-2 py-0.5 text-[11.5px] leading-4 font-medium",
              riskState.iconClassName,
            )}
          >
            {riskLabel ?? riskState.label}
          </span>
          <span
            className={cn(
              "inline-flex items-center gap-1.5 text-[11.5px] leading-4 text-[var(--uai-subtle)]",
              context.status === "approved" && "text-[var(--uai-success)]",
              context.status === "rejected" && "text-[var(--uai-muted)]",
              context.status === "error" && "text-[var(--uai-danger)]",
            )}
            role="status"
            aria-live="polite"
          >
            {context.isSubmitting ? (
              <LoaderCircle
                className="size-3 animate-spin motion-reduce:animate-none"
                aria-hidden="true"
              />
            ) : context.status === "approved" ? (
              <Check className="size-3 text-[var(--uai-success)]" aria-hidden="true" />
            ) : context.status === "rejected" ? (
              <X className="size-3 text-[var(--uai-danger)]" aria-hidden="true" />
            ) : context.status === "error" ? (
              <CircleAlert className="size-3 text-[var(--uai-danger)]" aria-hidden="true" />
            ) : null}
            <span data-shimmer={context.isSubmitting ? "" : undefined}>{resolvedStatusLabel}</span>
          </span>
        </div>
        <h3
          id={context.titleId}
          className="mt-2 text-[14px] leading-5 font-medium tracking-[-0.005em] text-balance"
        >
          {title}
        </h3>
        {description ? (
          <p className="mt-1 max-w-[68ch] text-[13px] leading-[19px] text-pretty text-[var(--uai-muted)]">
            {description}
          </p>
        ) : null}
      </div>
    </div>
  );
}

export type ApprovalCardDetailsProps = ComponentProps<"dl">;

export function ApprovalCardDetails({ children, className, ...props }: ApprovalCardDetailsProps) {
  const context = useApprovalCard("ApprovalCardDetails");
  if (context.variant !== "detailed") return null;

  return (
    <dl
      className={cn(
        "mt-4 grid gap-x-4 gap-y-3 rounded-[10px] bg-[color-mix(in_oklab,var(--uai-surface-raised)_55%,transparent)] p-3 sm:grid-cols-2",
        className,
      )}
      {...props}
    >
      {children}
    </dl>
  );
}

export type ApprovalCardDetailProps = ComponentProps<"div"> & { label: ReactNode };

export function ApprovalCardDetail({
  label,
  children,
  className,
  ...props
}: ApprovalCardDetailProps) {
  return (
    <div className={cn("min-w-0", className)} {...props}>
      <dt className="text-[11.5px] leading-4 text-[var(--uai-subtle)]">{label}</dt>
      <dd className="mt-1 min-w-0 text-[13px] leading-[18px] text-[var(--uai-text)] [&_code]:rounded-md [&_code]:bg-[var(--uai-surface-raised)] [&_code]:px-1.5 [&_code]:py-px [&_code]:font-mono [&_code]:text-[11.5px] [&_li+li]:mt-1 [&_ul]:list-inside [&_ul]:list-disc [&_ul]:marker:text-[var(--uai-subtle)]">
        {children}
      </dd>
    </div>
  );
}

export type ApprovalCardConfirmationProps = ComponentProps<"div">;

export function ApprovalCardConfirmation({ className, ...props }: ApprovalCardConfirmationProps) {
  const context = useApprovalCard("ApprovalCardConfirmation");
  if (context.risk !== "critical" || context.isTerminal || !context.confirmation) return null;

  return (
    <div className={cn("mt-4", className)} {...props}>
      <label
        htmlFor={context.confirmationId}
        className="block text-[12.5px] leading-[18px] text-[var(--uai-muted)]"
      >
        {context.confirmation.label ?? (
          <>
            Type{" "}
            <strong className="rounded-md bg-[var(--uai-surface-raised)] px-1.5 py-px font-mono text-[11.5px] font-medium text-[var(--uai-text)]">
              {context.confirmation.phrase}
            </strong>{" "}
            to confirm.
          </>
        )}
      </label>
      <input
        id={context.confirmationId}
        type="text"
        value={context.confirmationValue}
        placeholder={context.confirmation.placeholder ?? context.confirmation.phrase}
        autoComplete="off"
        spellCheck={false}
        disabled={context.disabled || context.isSubmitting}
        onChange={(event) => context.setConfirmationValue(event.target.value)}
        className="mt-2 h-9 w-full rounded-[10px] border border-transparent bg-[var(--uai-canvas)] px-3 font-mono text-[12.5px] text-[var(--uai-text)] caret-[var(--uai-text)] outline-none transition-[border-color,box-shadow] duration-[120ms] ease-out placeholder:text-[var(--uai-subtle)] focus-visible:border-[var(--uai-border-strong)] focus-visible:ring-2 focus-visible:ring-[color-mix(in_oklab,var(--uai-accent)_45%,transparent)] selection:bg-[color-mix(in_oklab,var(--uai-text)_18%,transparent)] disabled:cursor-not-allowed motion-reduce:transition-none"
      />
    </div>
  );
}

export type ApprovalCardErrorProps = ComponentProps<"p">;

export function ApprovalCardError({ className, children, ...props }: ApprovalCardErrorProps) {
  const context = useApprovalCard("ApprovalCardError");
  if (context.status !== "error") return null;

  return (
    <p
      className={cn(
        "mt-4 flex items-start gap-2 rounded-[10px] bg-[color-mix(in_oklab,var(--uai-danger)_10%,transparent)] px-3 py-2.5 text-[13px] leading-[18px] text-[var(--uai-text)]",
        className,
      )}
      {...props}
      role="alert"
    >
      <CircleAlert
        className="mt-0.5 size-3.5 shrink-0 text-[var(--uai-danger)]"
        aria-hidden="true"
      />
      {children}
    </p>
  );
}

export type ApprovalCardActionsProps = ComponentProps<"div">;

export function ApprovalCardActions({ className, children, ...props }: ApprovalCardActionsProps) {
  const context = useApprovalCard("ApprovalCardActions");
  if (context.isTerminal) return null;

  return (
    <div className={cn("mt-4 flex flex-wrap items-center justify-end gap-2", className)} {...props}>
      {children}
    </div>
  );
}

export type ApprovalCardRejectProps = ComponentProps<"button">;

export function ApprovalCardReject({
  children = "Reject",
  className,
  disabled,
  ...props
}: ApprovalCardRejectProps) {
  const context = useApprovalCard("ApprovalCardReject");

  return (
    <button
      {...props}
      type="button"
      className={cn(
        "h-8 rounded-full bg-[var(--uai-surface-raised)] px-3.5 text-[13px] font-medium text-[var(--uai-text)] outline-none transition-[background-color,transform] duration-[140ms] ease-[cubic-bezier(0.23,1,0.32,1)] enabled:hover:bg-[color-mix(in_oklab,var(--uai-surface-raised)_85%,var(--uai-text))] focus-visible:ring-2 focus-visible:ring-[var(--uai-accent)] enabled:active:scale-[0.97] disabled:cursor-not-allowed disabled:opacity-50 motion-reduce:transition-none motion-reduce:active:scale-100",
        className,
      )}
      disabled={context.disabled || !context.isActionable || disabled}
    >
      {children}
    </button>
  );
}

export type ApprovalCardApproveProps = ComponentProps<"button">;

export function ApprovalCardApprove({
  children = "Approve",
  className,
  disabled: disabledProp,
  ...props
}: ApprovalCardApproveProps) {
  const context = useApprovalCard("ApprovalCardApprove");
  const disabled =
    context.disabled || !context.isActionable || !context.confirmationMatches || disabledProp;

  return (
    <button
      {...props}
      type="button"
      className={cn(
        "h-8 rounded-full px-3.5 text-[13px] font-medium outline-none transition-[filter,opacity,transform] duration-[140ms] ease-[cubic-bezier(0.23,1,0.32,1)] enabled:hover:brightness-[1.08] focus-visible:ring-2 focus-visible:ring-[var(--uai-accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--uai-surface)] enabled:active:scale-[0.97] disabled:cursor-not-allowed disabled:opacity-45 motion-reduce:transition-none motion-reduce:active:scale-100",
        context.risk === "critical"
          ? "bg-[var(--uai-danger)] text-[var(--uai-accent-foreground)]"
          : "bg-[var(--uai-accent)] text-[var(--uai-accent-foreground)]",
        className,
      )}
      disabled={disabled}
    >
      {context.isSubmitting && context.pendingDecision === "approved" ? "Approving…" : children}
    </button>
  );
}
